"""Explain length conversion and KMSAN initialization metadata."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1673': ('큰 숫자를 적는 칸에서 작은 칸으로 옮길 때 같은 숫자를 다 담지 못할 수 있어요. 함수에 길이를 넘길 때도 받는 자료형의 범위를 확인해야 해요.', '길이 인자의 타입 변환과 실제 버퍼 검사를 구별합니다.', 'unsigned int가 32비트이고 size_t가 64비트라고 가정하세요. 4294967296을 unsigned int로 바꾸면 0이라는 계산을 적으세요.', ['자료형은 값의 종류와 표현할 수 있는 범위를 정해요. 이름이 둘 다 size라고 해서 자료형도 같다는 뜻은 아니에요. 호출하는 쪽과 받는 함수의 선언을 따로 읽어야 해요.', 'instrument_read 같은 바깥 도우미는 길이를 size_t로 받아요. 하지만 __kasan_check_read와 __kasan_check_write의 size 매개변수는 unsigned int예요. 매개변수는 함수가 전달받는 값의 자리예요.', 'unsigned는 음수가 없는 정수 형식이에요. unsigned int가 32비트라면 0부터 4294967295까지 표현해요. 이 최대값을 UINT_MAX라고 불러요. size_t의 폭과 unsigned int의 폭이 항상 같은 것은 아니에요.', 'size_t가 64비트인 예시에서 4294967296을 unsigned int로 변환하면 4294967296으로 나눈 나머지인 0이 돼요. 그 큰 값은 먼저 넓은 자료형으로 준비했다고 가정해요. 범위를 넘은 값을 작은 unsigned 형식으로 옮기는 규칙을 보여 주는 계산이에요.', '같은 상황에서 size_t를 받는 KCSAN 경로는 그 큰 값을 그대로 받을 수 있어요. 따라서 바깥에서 같은 길이를 전달해도 각 검사 함수가 받는 형식 때문에 기록 값이 달라질 수 있어요. 모든 플랫폼이 이 예시와 같은 폭을 가진다는 뜻은 아니에요.', '인자를 기록하는 모델에서 0으로 바뀌는 것을 확인해도 실제 큰 버퍼를 안전하게 읽었다는 증거는 아니에요. 실제 객체의 길이, 주소의 유효성, 각 함수의 허용 범위를 별도로 확인해야 해요. 변환 결과 0은 거대한 접근이 안전하다는 허가가 아니에요.'], [('이 직접 KASAN 검사 함수에서 size의 자료형은 무엇인가요?', ['모든 플랫폼에서 size_t예요', 'unsigned int예요'], '정답은 두 번째예요. 함수 선언에 unsigned int size라고 적혀 있어요. 바깥 도우미의 size_t와 이름이 같은 길이 인자여도 타입은 다를 수 있어요.'), ('큰 길이의 인자 변환을 기록하면 실제 거대한 버퍼의 안전성까지 확인한 것인가요?', ['아니요. 타입 변환 경계를 확인한 것이에요', '네. UINT_MAX보다 큰 모든 버퍼를 검사한 것이에요'], '정답은 첫 번째예요. 기록 도우미는 받은 숫자를 보여 줄 수 있지만 그 크기의 실제 메모리 접근을 수행한 것은 아니에요. 주소와 범위의 안전성은 별도 증거가 필요해요.')]), 'os1674': ('답안지에 글자가 보이더라도 정식으로 답을 적었는지 표시가 필요할 수 있어요. 메모리의 숫자와 그 숫자가 초기화됐는지에 대한 검사 기록은 달라요.', 'KMSAN poison의 미초기화 기록과 flags·origin을 이해합니다.', '버퍼 4칸과 초기화 기록 4칸을 나란히 그리세요. poison은 기록에 미초기화 표시를 하고 버퍼를 0으로 채우는 일은 아니라고 적으세요.', ['KMSAN은 아직 유효한 값으로 초기화되지 않은 데이터를 사용하는 문제를 찾는 검사 도구예요. 초기화는 사용하기 전에 알맞은 값을 채우는 일이에요. 메모리 칸에 어떤 비트가 보인다는 것만으로 올바른 초기화가 끝났다고 할 수는 없어요.', 'kmsan_poison_memory는 지정한 범위를 미초기화로 표시하는 인터페이스예요. poison은 여기서 검사기가 그 범위를 미초기화로 취급하도록 기록한다는 뜻이에요. 버퍼에 독특한 바이트 패턴을 써 넣는 일반 데이터 함수라는 뜻이 아니에요.', 'metadata는 실제 데이터를 설명하는 부가 정보예요. 여기서는 어느 부분이 초기화되었는지 등을 추적해요. 실제 버퍼 값과 그 상태를 기록한 metadata를 두 줄로 나누어 보면 이해하기 쉬워요.', 'address는 시작 주소이고 size는 표시할 범위의 길이예요. flags는 버퍼에 넣을 숫자가 아니라 이 함수가 메모리를 할당할 때 사용할 GFP 조건이에요. GFP flags는 커널에서 메모리를 얻을 때 허용할 동작 등을 알리는 설정값이에요.', 'origin은 오류 보고에서 미초기화 상태가 어디서 왔는지 찾는 출처 정보예요. 이 함수로 표시한 메모리의 오류 보고는 poison을 호출한 위치를 출처로 가리킨다고 헤더가 설명해요. 대상 주소와 코드의 호출 위치는 다른 정보예요.', '따라서 flags에 어떤 값을 주어도 그것을 memset처럼 데이터에 반복해서 채운다고 읽으면 안 돼요. memset은 실제 바이트를 채우는 함수예요. 이 선언은 검사 상태의 표시 계약이며 실제 추적 자료구조와 보고 과정은 구현을 따로 따라가야 해요.'], [('kmsan_poison_memory의 flags는 무엇을 위한 인자인가요?', ['버퍼의 각 바이트에 채울 숫자예요', '이 함수의 메모리 할당에 사용할 GFP 조건이에요'], '정답은 두 번째예요. 헤더는 이 함수가 수행하는 할당의 GFP flags라고 설명해요. 표시할 길이는 size이고 데이터에 채울 바이트 값은 이 함수의 인자가 아니에요.'), ('poison을 일반 memset처럼 이해해도 되나요?', ['아니요. 미초기화 상태를 기록하는 metadata 표시예요', '네. 대상의 모든 바이트를 0으로 만들어요'], '정답은 첫 번째예요. 검사 상태와 실제 데이터를 나누어 보세요. 미초기화라고 표시하는 호출이 버퍼를 0으로 초기화하는 작업을 대신하지 않아요.')]), 'os1675': ('아직 답을 쓰지 않은 칸에 작성 완료 도장을 찍으면 점검하는 사람이 빈칸을 놓칠 수 있어요. 초기화 완료 표시도 실제로 채운 범위와 맞아야 해요.', 'unpoison 표시와 실제 데이터 초기화를 구별합니다.', '8바이트 중 앞 3바이트만 유효하게 전달됐다고 가정하세요. 앞 3칸은 채움, 뒤 5칸은 미초기화로 그리고 전체 완료 표시의 문제를 적으세요.', ['kmsan_unpoison_memory는 지정한 범위를 초기화된 것으로 표시해요. 초기화 상태를 추적하는 metadata를 다루는 인터페이스예요. 함수 이름의 unpoison을 실제 데이터를 새로 만드는 동작으로 읽으면 안 돼요.', '이 함수는 일반 memset처럼 버퍼에 0을 채우는 함수가 아니에요. 예를 들어 데이터 칸의 숫자가 7인 상태에서 검사 표시를 바꿨다고 그 숫자를 0으로 바꾸는 작업을 한 것이 아니에요.', '컴파일러가 관찰하지 못하는 경로로 유효한 데이터가 전달되면 추적 기록에도 그 사실을 알려야 할 수 있어요. 그때 실제로 채워진 주소와 길이에 맞추어 초기화 표시를 조정해요. 사실에 맞는 표시가 중요한 이유예요.', '연습으로 8바이트 버퍼의 앞 3바이트만 채워졌다고 해 보세요. 뒤 5바이트가 아직 미초기화라면 전체 8바이트에 완료 표시를 붙이는 것은 실제 상태와 달라요. 8 - 3 = 5바이트의 문제를 검사에서 가릴 수 있어요.', '원문은 다른 데이터가 해당 범위에 쓰이기 전까지 KMSAN이 초기화된 것으로 취급한다고 설명해요. 영원히 초기화 상태가 고정되거나 나중에 어떤 데이터를 써도 안전하다는 뜻은 아니에요. 새 데이터의 상태 추적도 이어져야 해요.', 'CONFIG_KMSAN이 꺼진 경우에는 빈 inline 구현이 선택돼요. 이때 함수 이름이 코드에 남아 있어도 실제 검사 기록을 바꾸는 기능은 없어요. 활성 모드에서도 unpoison 표시만으로 실제 초기화나 잘못된 데이터의 복원이 이루어지지는 않아요.'], [('unpoison은 실제 대상 바이트를 0으로 쓰나요?', ['네. 버퍼를 안전하게 지우는 memset이에요', '아니요. 초기화된 것으로 metadata에 표시해요'], '정답은 두 번째예요. 원문의 계약은 초기화 상태 표시예요. 실제 데이터를 채우는 작업과 그 사실을 검사 도구에 알리는 작업을 구별하세요.'), ('아직 채우지 않은 버퍼까지 전부 unpoison하면 어떤 문제가 있나요?', ['미초기화 데이터 사용을 검사에서 놓치게 할 수 있어요', '원래 데이터가 자동으로 복원돼요'], '정답은 첫 번째예요. 실제 상태보다 넓게 초기화됐다고 알리면 뒤의 미초기화 바이트를 찾는 목적을 해쳐요. 표시를 바꿔도 빠진 데이터를 만들거나 복원하지는 않아요.')]), 'os1676': ('답안지 8칸 중 7칸을 채웠더라도 남은 한 칸은 여전히 확인해야 해요. 범위 검사는 전체가 비었을 때만 문제가 되는 것이 아니에요.', '일부 미초기화 범위와 KASAN·KCSAN·KMSAN의 질문을 구별합니다.', '8칸 중 마지막 칸만 미초기화로 그리세요. 주소가 유효한가 / 값을 채웠는가 / 동시 접근이 안전한가를 세 줄로 적으세요.', ['kmsan_check_memory는 address에서 시작하는 size 길이의 메모리가 초기화된 것으로 표시되어 있는지 확인하는 인터페이스예요. 주소는 시작 위치이고 길이는 검사할 범위예요.', '헤더는 그 범위의 일부라도 미초기화로 표시되어 있으면 오류를 보고한다고 설명해요. 예를 들어 8바이트 중 앞 7바이트만 초기화되었다면 남은 1바이트도 문제예요. 모든 바이트가 미초기화여야 보고하는 규칙이 아니에요.', '초기화 여부는 숫자가 0인지 아닌지로 판단하는 것이 아니에요. 올바르게 0을 쓴 칸은 초기화될 수 있고, 우연히 메모리에 0이 보이는 칸은 미초기화일 수 있어요. 추적 기록과 실제 데이터의 숫자를 구별하세요.', 'KASAN의 질문은 그 메모리 접근이 유효한 범위와 수명 안에 있는가에 가까워요. KMSAN은 사용하려는 값이 초기화되었는가를 추적해요. 유효한 버퍼를 할당받았더라도 내용을 채우지 않았다면 두 질문의 답이 달라질 수 있어요.', 'KCSAN은 여러 실행 흐름의 접근이 충돌하는 문제를 다뤄요. 혼자 사용하는 버퍼라도 초기화를 빼먹을 수 있고, 초기화한 버퍼라도 여러 작업이 잘못 겹쳐 접근할 수 있어요. 그래서 세 도구의 질문을 같은 것으로 합치면 안 돼요.', '이 검사 함수는 잠금을 잡거나 빈칸에 데이터를 채우는 함수가 아니에요. CONFIG_KMSAN이 꺼지면 빈 대체 구현이므로 실제 검사를 수행하지 않아요. 선언과 인자 전달을 확인한 것만으로 실제 오류 보고까지 시험했다고 주장할 수도 없어요.'], [('검사 범위의 일부 바이트만 미초기화여도 헤더의 계약상 오류 보고 대상인가요?', ['아니요. 모든 바이트가 미초기화여야 해요', '네. 일부라도 미초기화로 표시되어 있으면 대상이에요'], '정답은 두 번째예요. 원문은 any piece라고 설명해요. 8바이트 중 1바이트만 남았어도 전체 8바이트가 모두 초기화되었다는 조건을 충족하지 못해요.'), ('KMSAN 초기화 검사와 KCSAN의 주된 질문은 같나요?', ['아니요. 초기화 상태와 동시 접근 문제는 달라요', '네. 둘 다 자동으로 잠금을 잡는 함수예요'], '정답은 첫 번째예요. 값이 준비됐는지와 여러 작업의 접근이 안전한지는 다른 조건이에요. 검사 요청 자체가 실제 데이터를 보호하는 잠금 획득도 아니에요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_414.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
